#!/usr/bin/env bash
# ==============================================================================
# Itarang Phase 3 — poller hotfix v4
# Run as root on the Hostinger VPS.
#
# Builds on v3. Two changes:
#   1. `online` is now derived in SQL from the persisted last_gps_at
#      (after COALESCE), not from this-cycle's gps_t. A single transient
#      Intellicar data:null no longer flaps a vehicle offline.
#   2. OFFLINE_SEC raised from 30 → 60 minutes. EV depot/charge cycles
#      routinely exceed 30 min. Offline alerts are now triggered after
#      a full hour of silence.
#
# What this script does:
#   1. Backs up current poll.py (timestamped, .v4 suffix)
#   2. Writes the new poll.py via base64 (md5 verified — auto-rollback on mismatch)
#   3. Rebuilds the poller image and restarts the container
#   4. Tails the log for ~75s (3 cycles)
#   5. Prints post-fix counts AND freshness distribution
# ==============================================================================
set -euo pipefail

STORAGE_DIR=/opt/intellicar/storage
POLL_FILE="$STORAGE_DIR/poller/poll.py"
EXPECTED_MD5="472e75f26f42c67b3d5be12e21e79053"

cd "$STORAGE_DIR"

echo "==> [1/4] Backing up current poller/poll.py"
cp "$POLL_FILE" "$POLL_FILE.bak.v4.$(date +%s)"
ls -la "$STORAGE_DIR/poller/" | grep poll.py

echo "==> [2/4] Writing new poller/poll.py (base64, md5-verified)"
base64 -d > "$POLL_FILE" <<'B64_EOF'

B64_EOF

ACTUAL_MD5=$(md5sum "$POLL_FILE" | awk '{print $1}')
if [ "$ACTUAL_MD5" != "$EXPECTED_MD5" ]; then
  echo "    ERROR: md5 mismatch. expected=$EXPECTED_MD5 actual=$ACTUAL_MD5"
  echo "    File not applied. Restoring the most recent backup..."
  cp "$(ls -t $POLL_FILE.bak.* | head -1)" "$POLL_FILE"
  exit 1
fi
echo "    md5 ok ($ACTUAL_MD5)"
echo "    new file: $(wc -l < $POLL_FILE) lines"

echo "==> [3/4] Rebuilding poller image and restarting container"
docker compose build poller
docker compose up -d poller
docker compose ps poller

echo "==> [4/4] Tailing log for ~75s (3 poll cycles) to watch for errors"
timeout 75 docker compose logs --tail=0 -f poller || true

echo ""
echo "==> Post-fix counts"
docker compose exec -T postgres psql -U intellicar intellicar <<'SQL_EOF'
SELECT
  COUNT(*)                                AS total,
  COUNT(lat)                              AS with_lat,
  COUNT(soc_pct)                          AS with_soc,
  COUNT(*) FILTER (WHERE online)          AS online,
  COUNT(*) FILTER (WHERE online AND lat IS NULL) AS online_no_lat_BUG
FROM vehicle_state;

SELECT
  COUNT(*) FILTER (WHERE NOW() - last_gps_at < INTERVAL '5 min')   AS last_5min,
  COUNT(*) FILTER (WHERE NOW() - last_gps_at < INTERVAL '30 min')  AS last_30min,
  COUNT(*) FILTER (WHERE NOW() - last_gps_at < INTERVAL '1 hour')  AS last_1h,
  COUNT(*) FILTER (WHERE NOW() - last_gps_at < INTERVAL '6 hours') AS last_6h,
  COUNT(*) FILTER (WHERE NOW() - last_gps_at < INTERVAL '24 hours') AS last_24h
FROM vehicle_state;

-- Open offline alerts (should be far fewer than before)
SELECT COUNT(*) AS open_offline_alerts
FROM alerts
WHERE alert_type = 'offline' AND resolved_at IS NULL;
SQL_EOF

echo ""
echo "================================================================="
echo " Hotfix v4 complete."
echo ""
echo " Expected outcome:"
echo "   online       ~= last_1h       (no more transient flapping)"
echo "   open_offline  drops sharply   (only truly silent vehicles flagged)"
echo "================================================================="
